\textbf{Proof}:\  The proof of the first integral representation (\ref{PV17}) follows by use of the extended beta function (\ref{ES20}) in (\ref{PV16}), a change the order of integration and summation (with uniform convergence of the integral) and, after simplification, use of Exton's triple hypergeometric function (\ref{PV3}), to obtain the right-hand side of the result (\ref{PV17}). The integral representations (\ref{PV18})-(\ref{PV23}) can be proved directly by using the following transformations
\begin{eqnarray*}
(\ref{PV18}):\qquad t&=&\frac{(\beta-\gamma)(\xi-\alpha)}{(\beta-\alpha)(\xi-\gamma)},\quad \frac{dt}{d\xi}=\frac{(\beta-\gamma)(\alpha-\gamma)}{(\beta-\alpha) (\xi-\gamma)^2},\\
(\ref{PV20}):\qquad t&=& \sin^2 \xi,\quad \frac{dt}{d\xi}=2\sin \xi \cos \xi\\
(\ref{PV21}):\qquad t&=&\frac{(1+\lambda)\sin^{2}\xi}{1+\lambda \sin^{2}\xi},\quad\frac{dt}{d\xi}=\frac{2(1+\lambda)\sin \xi \cos \xi}{(1+\lambda \sin^2 \xi)^2},\\
(\ref{PV23}):\qquad t&=&\frac{\lambda \sin^{2}\xi}{\cos^2{\xi}+\lambda \sin^{2}\xi},\quad \frac{dt}{d\xi}=\frac{2\lambda \sin \xi \cos \xi}{(\cos^2\xi+\lambda \sin^2\xi)^2}\\ 
\end{eqnarray*}
in turn in (\ref{PV17}) to obtain the right-hand side of each result.
\vspace{0.6cm}

\begin{center}
{\bf 3. \  The Mellin transform for $H_{B,p,\nu}(\cdot)$}
\end{center}
\setcounter{section}{3}
\setcounter{equation}{0}

The Mellin transform of a locally integrable function $f(x)$ on $(0,\infty)$ is given by (see, for example,  \cite[p.193, Section 2.1]{AB125})
\begin{equation}\label{PV27}
\Phi(s)={\cal M}\left\{f(x)\right\}(s)=\int_{0}^{\infty}x^{s-1}f(x)\,dx
\end{equation}
which defines an analytic function in its strip of analyticity $a<\Re (s)<b$.
The inverse Mellin transform of the above function (\ref{PV27}) is defined by
\begin{equation}\label{PV28}
f(x)={\cal M}^{-1}\left\{\Phi(s)\right\}=\frac{1}{2\pi i}\int_{c-i\infty}^{c+i\infty}x^{-s}\Phi(s)\,ds \qquad (a<c<b).
\end{equation}

\noindent
\textbf{Proof}: Substituting the extended Srivastava function (\ref{PV16}) into the integral on the left-hand side of (\ref{PV30}) and changing the order of integration (by the uniform convergence of the integral), we obtain
\[{\cal M}\left\{H_{B,p,\nu}(b_{1},b_{2},b_{3};c_{1},c_2,c_3;x,y,z)\right\}(s)\hspace{3cm}\] \[=\sum_{m,n,k=0}^{\infty}\frac{(b_{1}+b_{2})_{2m+n+k}(b_{3})_{n+k}}{(c_{1})_{m}(c_{2})_{n}(c_{3})_{k}~B(b_{1},b_{2})}\frac{x^{m}}{m!}\frac{y^{n}}{n!}\frac{z^{k}}{k!}
  \left\{\int_{0}^{\infty}p^{s-1}B_{p,\nu}(b_{1}+m+k,b_{2}+m+n)\,dp\right\}.
\]
Using the extended Beta function (\ref{ES20}) then shows that

\[{\cal M}\left\{H_{B,p,\nu}(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z)\right\}(s)
=\sqrt{\frac{2}{\pi}}\sum_{m,n,k=0}^{\infty}\frac{(b_{1}+b_{2})_{2m+n+k}(b_{3})_{n+k}}{(c_{1})_{m}(c_{2})_{n}(c_{3})_{k}~B(b_{1},b_{2})}\frac{x^{m}}{m!}\frac{y^{n}}{n!}\frac{z^{k}}{k!}\]
\[\times\int_{0}^{1}t^{b_{1}+m+k-\frac{3}{2}}(1-t)^{b_{2}+m+n-\frac{3}{2}} \left\{\int_{0}^{\infty}p^{s-\frac{1}{2}}K_{\nu+\frac{1}{2}}\left(\frac{p}{t(1-t)}\right)dp\right\}dt.\]
Application of the result \cite[(10.43.19)]{AB26}
\[\int_{0}^{\infty}w^{s-\frac{1}{2}}K_{\alpha+\frac{1}{2}}(w)dw=2^{s-\frac{3}{2}}\Gamma\left(\frac{s-\alpha}{2}\right)
\Gamma\left(\frac{s+\alpha+1}{2}\right)\qquad (|\Re (\alpha)|<\Re (s))\]
followed by the substitution $w=p/(t(1-t))$ produces
\begin{eqnarray*}\label{PV34}
{\cal M}\left\{H_{B,p,\nu}(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z)\right\}(s)
=\frac{2^{s-1}}{\sqrt{\pi}}\Gamma\left(\frac{s-\nu}{2}\right)\Gamma\left(\frac{s+\nu+1}{2}\right)
\nonumber\\ \times\sum_{m,n,k=0}^{\infty}\frac{(b_{1}+b_{2})_{2m+n+k}(b_{3})_{n+k}}{(c_{1})_{m}(c_{2})_{n}(c_{3})_{k}~B(b_{1},b_{2})}\frac{x^{m}}{m!}\frac{y^{n}}{n!}\frac{z^{k}}{k!}
\left\{\int_{0}^{1}t^{b_{1}+m+k+s-1}(1-t)^{b_{2}+m+n+s-1}dt\right\}.
\end{eqnarray*}
Evaluation of the integral in terms of the classical Beta function then finally yields
\begin{eqnarray*}\label{PV35}
\Phi(s)={\cal M}\left\{H_{B,p,\nu}(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z)\right\}(s)
=\frac{2^{s-1}}{\sqrt{\pi}}\Gamma\left(\frac{s-\nu}{2}\right)\Gamma\left(\frac{s+\nu+1}{2}\right)\\  \times\sum_{m,n,k=0}^{\infty}\frac{(b_{1}+b_{2})_{2m+n+k}(b_{3})_{n+k}}{(c_{1})_{m}(c_{2})_{n}(c_{3})_{k}}
\frac{B(b_{1}+m+k+s,b_{2}+m+n+s)}{B(b_{1},b_{2})}\frac{x^{m}}{m!}\frac{y^{n}}{n!}\frac{z^{k}}{k!}.
\end{eqnarray*}
Identifying the above sum as $H_B^{(s)}(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z)$ in (\ref{PV2a}), we obtain the right-hand side of (\ref{PV30}).


\bigskip

\noindent
\textbf{Corollary 1}: \ The following inverse Mellin formula for $H_{B,p,\nu}(\cdot)$ holds:
\[H_{B,p,\nu}(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z)={\cal M}^{-1}\left\{\Phi(s)\right\}\hspace{4cm}\]
\begin{equation}\label{PV36}
=\frac{\pi^{-3/2}}{4i}\int_{c-i\infty}^{c+i\infty}\left(\frac{2}{p}\right)^{s}\Gamma\left(\frac{s\!-\!\nu}{2}\right)\Gamma\left(\frac{s\!+\!\nu\!+\!1}{2}\right)
H_{B}^{(s)}\left(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z\right)ds,
\end{equation}
where $c>\nu$.
\vspace{0.6cm}

\begin{center}
{\bf 4. \  A differentiation formula for $H_{B,p,\nu}(\cdot)$}
\end{center}
\setcounter{section}{4}
\setcounter{equation}{0}

\noindent
\textbf{Proof}:\ If we differentiate partially the series for ${\cal H}\equiv H_{B,p,\nu}(b_{1},b_{2},b_{3};c_{1},c_{2},c_{3};x,y,z)$ in (\ref{PV16}) with respect to $x$ we obtain
\[\frac{\partial{\cal H}}{\partial x}
=\sum_{m=1}^\infty \sum_{n,k=0}^\infty \frac{(b_1+b_2)_{2m+n+k} (b_3)_{n+k}}{(c_1)_m(c_2)_n(c_3)_k}\,\frac{B_{p,\nu}(b_1+m+k,b_2+m+n)}{B(b_1, b_2)}\,\frac{x^{m-1}}{(m-1)!}\frac{y^n}{n!} \frac{z^k}{k!}.\]
Making use of the fact that 
\begin{equation}\label{eB}
B(b_1,b_2)=\frac{(b_1+b_2)_2}{b_1 b_2}\,B(b_1+1, b_2+1)
\end{equation}
and $(\lambda)_{m+n}=(\lambda)_m(\lambda+m)_n$, we have upon setting $m \to m+1$
\[\frac{\partial{\cal H}}{\partial x}
=\frac{b_1 b_2}{c_1} \sum_{m,n,k=0}^\infty \frac{(b_1+b_2+2)_{2m+n+k} (b_3)_{n+k}}{(c_1+1)_m(c_2)_n(c_3)_k}\,\frac{B_{p,\nu}(b_1\!+\!1\!+\!m\!+\!k,b_2\!+\!1\!+\!m\!+\!n)}{B(b_1+1, b_2+1)}\,\frac{x^{m}}{m!}\frac{y^n}{n!} \frac{z^k}{k!}\]
\begin{equation}\label{e41}
=\frac{b_1 b_2}{c_1}\,H_{B,p,\nu}(b_1+1,b_2+1,b_3;c_1+1,c_2,c_3;x,y,z).
\end{equation}
Repeated application of (\ref{e41}) then yields for $M=1, 2, \ldots $
\[\frac{\partial^M}{\partial x^M}{\cal H}=
\frac{(b_1)_M (b_2)_M}{(c_1)_M}\,H_{B,p,\nu}(b_{1}+M,b_{2}+M,b_{3};c_{1}+M,c_{2},c_{3};x,y,z).\]

A similar reasoning shows that
\[\frac{\partial^{M+1}}{\partial x^M \partial y}{\cal H}
=\frac{(b_1)_M (b_2)_M}{(c_1)_M} \sum_{m,k=0}^\infty \sum_{n=1}^\infty \frac{(b_1\!+\!b_2\!+\!2M)_{2m+n+k} (b_3)_{n+k}}{(c_1\!+\!M)_m (c_2)_n(c_3)_k}\hspace{3cm}\]
\[\hspace{3cm}\times\frac{B_{p, \nu}(b_1\!+\!M\!+\!m\!+\!k,b_2\!+\!M\!+\!n\!+\!k)}{B(b_1\!+\!M, b_2\!+\!M)}\,\frac{x^m}{m!} \frac{y^{n-1}}{(n-1)!}\frac{z^k}{k!}\]
\begin{equation}\label{e42}
=\frac{(b_1)_{M} (b_2)_{M+1} b_3}{(c_1)_{M}c_2}\,H_{B,p,\nu}(b_1+M,b_2+M+1,b_3+1;c_1+M,c_2+1,c_3;x,y,z)
\end{equation}
upon putting $n\to n+1$ and using the property of the Beta function in (\ref{ES5}).
Repeated differentiation of (\ref{e42}) $N$ times with respect to $y$ then produces 
\[\frac{\partial^{M+N}}{\partial x^M \partial y^N} {\cal H}=\frac{(b_1)_M (b_2)_{M+N} (b_3)_N}{(c_1)_M (c_2)_N}\,
H_{B,p,\nu}(b_1\!+\!M,b_2\!+\!M\!+\!N,b_3\!+\!N;c_1\!+\!M,c_2\!+\!N,c_3;x,y,z).\]

Application of the same procedure to deal with differentiation with respect to $z$ then yields the result stated in (\ref{PV37}).

